    margin-left: 20px;

    img {
        margin-left: 5px;
    }
}

.mx_ProfileSettings_avatarUpload {
    display: none;
}

.mx_ProfileSettings_profileForm {
    @mixin mx_Settings_fullWidthField;
    border-bottom: 1px solid $menu-border-color;
}

