    margin-top: 10px; // 18px is already accounted for by the <p> above the buttons
    margin-bottom: 28px;

    > .mx_AccessibleButton_kind_link {
        padding-left: 0; // to align with left side
        padding-right: 0;
        margin-right: 10px;
    }
}
